<script setup lang="ts">
import {reactive,ref,onBeforeUnmount} from 'vue'
import type {Settings} from '@/api/vocabulary-learning'
import {saveLearningSettings} from '@/api/vocabulary-learning'
import {errorMessage} from '@/api/identity'
import {getGeneration} from '@/auth/token-session'
import {ApiError} from '@/api/client'
const props=defineProps<{settings:Settings}>(),emit=defineEmits<{saved:[];close:[];saving:[value:boolean]}>(),form=reactive({batchSize:20,autoNext:true,reviewScope:'ALL' as 'ALL'|'CURRENT',...props.settings}),busy=ref(false),error=ref('')
const fields=ref<Record<string,string>>({})
const controller=new AbortController();let disposed=false;onBeforeUnmount(()=>{disposed=true;controller.abort()})
async function save(){if(busy.value)return;const identity=getGeneration();busy.value=true;emit('saving',true);error.value='';fields.value={};try{await saveLearningSettings(form,controller.signal);if(!disposed&&identity===getGeneration())emit('saved')}catch(e){if(disposed||identity!==getGeneration())return;if(e instanceof ApiError&&e.fieldErrors)fields.value=e.fieldErrors;else error.value=errorMessage(e)}finally{busy.value=false;emit('saving',false)}}
</script>
<template><form class="vl-settings" @submit.prevent="save"><h2>学习计划</h2><div class="vl-presets"><button v-for="preset in [{name:'悠闲',n:5,r:30},{name:'轻松',n:10,r:60},{name:'标准',n:20,r:100},{name:'进阶',n:35,r:150},{name:'冲刺',n:50,r:200}]" :key="preset.name" type="button" :aria-pressed="form.newGoal===preset.n&&form.reviewGoal===preset.r" @click="form.newGoal=preset.n;form.reviewGoal=preset.r">{{ preset.name }}<small>{{ preset.n }} / {{ preset.r }}</small></button></div><label>每日新增目标（1–100）<input v-model.number="form.newGoal" type="number" min="1" max="100" required aria-describedby="vl-new-goal-error"><input v-model.number="form.newGoal" aria-label="每日新词滑块" type="range" min="1" max="100"><small id="vl-new-goal-error" class="vl-input-error">{{ fields.newGoal }}</small></label><label>每日复习目标（1–200）<input v-model.number="form.reviewGoal" type="number" min="1" max="200" required aria-describedby="vl-review-goal-error"><input v-model.number="form.reviewGoal" aria-label="复习目标滑块" type="range" min="1" max="200"><small id="vl-review-goal-error" class="vl-input-error">{{ fields.reviewGoal }}</small></label><label>每组单词数（1–50）<input v-model.number="form.batchSize" type="number" min="1" max="50" required aria-describedby="vl-batch-size-help vl-batch-size-error"><input v-model.number="form.batchSize" aria-label="每组单词数滑块" type="range" min="1" max="50"><small id="vl-batch-size-help" class="vl-muted">新学和复习共用，下一组生效；已开始的轮次保留原词数。</small><small id="vl-batch-size-error" class="vl-input-error">{{ fields.batchSize }}</small></label><label>复习范围<select v-model="form.reviewScope"><option value="ALL">全部学习来源</option><option value="CURRENT">当前词书</option></select></label><p class="vl-muted">看词和复习默写均手动继续；新词跟打连续完成整轮。</p><p class="vl-muted">新词和复习目标仅作参考，达标后仍可继续；剩余词数不足时按实际数量开始。</p><p v-if="error" role="alert" class="vl-input-error">{{ error }}</p><div class="vl-actions"><button class="vl-primary" :disabled="busy">保存目标</button><button type="button" :disabled="busy" @click="emit('close')">收起</button></div></form></template>
